Theorem mul_limb_step y v i : wordZ y -> 0 <= v ->
  let x := wordi v i in
  let c := mcarry y v i in
  let hl := DDproduct x y in
  let w := W.add (snd hl) c in
  w = wordi (y * v) i /\
  W.add (fst hl) (W.b2z (W.ltu w (snd hl))) = mcarry y v (S i).
