(* [comment removed for export] *)
Theorem add_limb0 y v : wordZ y -> 0 <= v ->
  let x := wordi v 0 in
  let w := W.add x y in
  w = wordi (v + y) 0 /\ W.b2z (W.ltu w x) = acarry y v 1.
