Theorem add_limbS y v i : wordZ y -> 0 <= v -> (1 <= i)%nat ->
  let x := wordi v i in
  let c := acarry y v i in
  let d := W.add x c in
  d = wordi (v + y) i /\
  acarry y v (S i) = (if c =? 1 then W.b2z (W.ltu d c) else 0).
