(* [comment removed for export] *)
Theorem mul_reduce_facts y v : wordZ y -> 1 <= y -> 0 < v ->
  let n := nwords v in let p := y * v in
  0 <= p < W.M ^ Z.of_nat (S n) /\
  (wordi p n = 0 -> nwords p = n /\ wordi p (n - 1) <> 0) /\
  (wordi p n <> 0 -> nwords p = S n).
