  let n := nwords v in let p := v + y in
  0 <= p < W.M ^ Z.of_nat (S n) /\
  (wordi p n = 0 -> nwords p = n /\ wordi p (n - 1) <> 0) /\
  (wordi p n <> 0 -> nwords p = S n).
