Theorem mul_word_is_wlist N s y s0 : okN N s -> reduced s -> wordZ y -> (S (size s) <= N)%nat ->
  let s' := fst (mul_word s y s0) in
  s_words s' = wlist (val (s_words s) * y) (nwords (val (s_words s) * y)) /\
